properties.query:
// HackSynth running on a host you monitor
// Agentic attack detections by ThreatDefence (HackSynth). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1610 (Deploy Container), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the HackSynth source code (aielte-research/HackSynth at 48a41f79). HackSynth is a Python research agent with no
// web UI. It runs:
//  - python run_bench.py -b <benchmark>.json -c <config>.json [-k] (run_bench.py:132-134)
//  - a kalilinux/kali-rolling container named attackbox_kali_pico, attackbox_kali_overthewire or attackbox, created
//    through the Docker API with NET_ADMIN, SYS_PTRACE and /dev/net/tun (docker_setup.py:20-32)
//  - once per new container: apt -y install kali-linux-headless sshpass curl, then ssh-keyscan -p 2220
//    bandit.labs.overthewire.org, -p 2231 krypton..., -p 2223 leviathan... (docker_setup.py:34-40)
//  - every model command as timeout 10s /bin/bash -c <command> through docker exec (pentest_agent.py:81)
// It writes no report or log file; the clone itself (pentest_agent.py, run_bench.py, docker_setup.py) is the file signal.
// Container processes show up only where the EDR sensor sees inside containers (Defender for Endpoint on the Linux host).

let Window = 30d;
let WrapperBurst = 10;   // wrapper processes from one device in an hour before it is worth a look
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "kali-linux-headless sshpass curl"
            or ProcessCommandLine has_any ("ssh-keyscan -p 2220 bandit.labs.overthewire.org", "ssh-keyscan -p 2231 krypton.labs.overthewire.org",
                "ssh-keyscan -p 2223 leviathan.labs.overthewire.org")
        | project Timestamp, DeviceName, Signal="HackSynth attackbox setup", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "run_bench.py" and ProcessCommandLine matches regex @"\s(-b|--benchmark)\s"
            and ProcessCommandLine has_any ("benchmark_solved.json", "combined_solved.json", "bandit_solved.json", "natas_solved.json",
                "configs/pico_bench/", "configs/overthewire_bench/")
        | project Timestamp, DeviceName, Signal="HackSynth launcher", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName == "timeout" and ProcessCommandLine matches regex @"^(\S*/)?timeout \d+s /bin/bash -c "
            and InitiatingProcessFileName in~ ("containerd-shim", "containerd-shim-runc-v2", "runc")
        | summarize Commands=count(), Examples=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp)
            by DeviceName, Hour=bin(Timestamp, 1h)
        | where Commands >= WrapperBurst
        | project Timestamp, DeviceName, Signal="HackSynth command wrapper burst", Detail=strcat(Commands, " commands: ", tostring(Examples)), Parent=""),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("pentest_agent.py", "run_bench.py", "docker_setup.py")
        | extend Folder=tostring(parse_path(FolderPath).DirectoryPath)
        | summarize Files=make_set(FileName, 5), Timestamp=min(Timestamp) by DeviceName, Folder
        | where array_length(Files) == 3
        | project Timestamp, DeviceName, Signal="HackSynth clone on disk", Detail=strcat(Folder, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// HackSynth attackbox download in proxy logs, and its one-login-per-command SSH pattern on targets
// Agentic attack detections by ThreatDefence (HackSynth). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1021.004 (Remote Services: SSH)
// Example hunt for Microsoft Sentinel. Test before alerting.
// From the HackSynth source code (aielte-research/HackSynth at 48a41f79). HackSynth sends no fixed user agent or marker
// to a target, so this hunt looks at two shapes instead:
//  - Proxy: the attackbox setup installs kali-linux-headless (docker_setup.py:36). The kalilinux/kali-rolling image
//    fetches packages over plain HTTP from http.kali.org, so the package name is in the URL. Any Kali build that
//    installs the same metapackage matches; look at which host did it.
//  - Target: the OverTheWire prompt makes every command start with sshpass -p <password> ssh <user>@<host> -p <port>
//    (configs/overthewire_bench/benchmarks/*.json:19), and every command is killed after 10 seconds
//    (pentest_agent.py:81). An SSH server sees one password login per step, each session over within about 10 seconds,
//    up to 20 in a row. Scripted checks and other tools look the same: this finds the shape, not HackSynth.

let Window = 14d;
let MinLogins = 5;      // short password logins from one source in an hour
let MaxSeconds = 12;    // 10 second timeout plus logging slack
let Accepted = Syslog
    | where TimeGenerated > ago(Window)
    | where ProcessName == "sshd" and SyslogMessage startswith "Accepted password for "
    | parse SyslogMessage with "Accepted password for " User " from " SrcIP " port " SrcPort " " *
    | project Start=TimeGenerated, Computer, User, SrcIP, SrcPort;
let Closed = Syslog
    | where TimeGenerated > ago(Window)
    | where ProcessName == "sshd" and SyslogMessage startswith "Disconnected from user "
    | parse SyslogMessage with "Disconnected from user " * " " SrcIP " port " SrcPort
    | project End=TimeGenerated, Computer, SrcIP, SrcPort;
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestURL has "kali-linux-headless"
        | summarize Requests=count(), URLs=make_set(substring(RequestURL, 0, 200), 5), TimeGenerated=min(TimeGenerated) by SourceIP
        | project TimeGenerated, Source="CommonSecurityLog", Signal="kali-linux-headless download (HackSynth attackbox setup)",
            Host=SourceIP, Detail=strcat(Requests, " requests: ", tostring(URLs))),
    (Accepted
        | join kind=inner Closed on Computer, SrcIP, SrcPort
        | extend Seconds=datetime_diff('second', End, Start)
        | where Seconds between (0 .. MaxSeconds)
        | summarize Logins=count(), Users=make_set(User, 10), TimeGenerated=min(Start) by Computer, SrcIP, Hour=bin(Start, 1h)
        | where Logins >= MinLogins
        | project TimeGenerated, Source="Syslog", Signal="Short SSH password logins in a row (HackSynth OverTheWire prompt shape)",
            Host=Computer, Detail=strcat(SrcIP, ": ", Logins, " logins under ", MaxSeconds, " s, users ", tostring(Users)))
| order by TimeGenerated desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (HackSynth). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". HackSynth has no addresses, domains or user agents of its own: its rows are command strings, container and
// folder names and prompt text, so this sweep looks in process command lines, file paths and proxy URLs.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "hacksynth" | project value=tostring(SearchKey), type, confidence, actor, source;
let Strings = toscalar(IOC | where type in ("string", "docker_image") and confidence in ("high", "medium") | summarize make_list(value));
let Paths = toscalar(IOC | where type in ("file_path", "file_name") and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | mv-apply s=Strings to typeof(string) on (where ProcessCommandLine has s | take 1 | project Indicator=s)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator, Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200))),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Paths)
        | mv-apply p=Paths to typeof(string) on (where FolderPath has p | take 1 | project Indicator=p)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator, Detail=strcat(DeviceName, " ", FolderPath)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (Strings)
        | mv-apply s=Strings to typeof(string) on (where RequestURL has s | take 1 | project Indicator=s)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator, Detail=strcat(SourceIP, " ", RequestURL))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc
